contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount: Ether to send to c.play; this contract will be msg.sender for the call
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint beforeCBalance = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterCBalance = address(c).balance;

        // General rule: if the call reverted then observable state of pot and contract balance is unchanged.
        // (This targets the requirement that incorrect ticket amounts revert without side-effects.)
        assert(reverted == true ? (afterPot == beforePot && afterCBalance == beforeCBalance) : true);
    }

    receive() external payable {}
}

